package com.company.tpm.notification;import com.company.tpm.config.AppProperties;import java.time.*;import org.slf4j.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ReminderWorker{private static final Logger log=LoggerFactory.getLogger(ReminderWorker.class);private final JdbcClient db;private final AppProperties props;public ReminderWorker(JdbcClient d,AppProperties p){db=d;props=p;}@Scheduled(cron="0 0 * * * *",zone="${app.timezone:Asia/Phnom_Penh}")@Transactional public void queueTrainingReminders(){for(int hours:new int[]{props.reminder().daysBefore()*24,props.reminder().hoursBefore(),props.reminder().finalHoursBefore()}){int n=db.sql("insert into notification_deliveries(recipient_id,channel,notification_type,logical_id,payload,status) select tp.employee_id,'TELEGRAM','TRAINING_REMINDER',concat('session:',s.id,':employee:',tp.employee_id,':hours:',:h),jsonb_build_object('sessionId',s.id,'hoursBefore',:h),'PENDING' from training_sessions s join training_participants tp on tp.session_id=s.id where s.status='SCHEDULED' and (s.session_date+s.start_time) between now()+(:h||' hours')::interval and now()+((:h+1)||' hours')::interval on conflict(logical_id,channel,recipient_id) do nothing").param("h",hours).update();log.info("module=reminder action=queue hoursBefore={} queued={}",hours,n);}}}
